{"source":"#!/usr/bin/env python3
"""Summarize a CSV with category,amount,status — only 'paid' rows."""

import csv
import json
import sys
from decimal import Decimal, ROUND_HALF_UP

TWO_PLACES = Decimal("0.01")


def normalize_category(raw: str) -> str:
    collapsed = " ".join(raw.split())  # collapse all whitespace
    folded = collapsed.casefold()
    return folded if folded else "uncategorized"


def process(input_path: str) -> dict:
    totals: dict[str, Decimal] = {}

    with open(input_path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            status = (row.get("status") or "").strip().casefold()
            if status != "paid":
                continue

            cat = normalize_category(row.get("category") or "")
            amt = Decimal(row.get("amount", "0").strip())
            rounded = amt.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)

            totals[cat] = totals.get(cat, Decimal("0")) + rounded

    # Build sorted categories list
    categories = sorted(
        [{"category": name, "total": str(total.quantize(TWO_PLACES, rounding=ROUND_HALF_UP))}
         for name, total in totals.items()],
        key=lambda c: c["category"],
    )

    grand_total = sum((c["total"] for c in categories), Decimal("0")).quantize(
        TWO_PLACES, rounding=ROUND_HALF_UP
    )

    return {"categories": categories, "total": str(grand_total)}


def main() -> None:
    path = sys.argv[1]
    result = process(path)
    print(json.dumps(result))


if __name__ == "__main__":
    main()"}

